package de.fitnesscoach.domain.fitness;

import java.time.*;import java.util.*;import de.fitnesscoach.data.repository.FitnessCoachRepository;import de.fitnesscoach.data.entity.*;

public final class FitnessIntelligenceService {private final FitnessCoachRepository repo;private final BaselineCalculator baselines=new BaselineCalculator();private final TrainingLoadCalculator load=new TrainingLoadCalculator();private final RecoveryCalculator recovery=new RecoveryCalculator();public FitnessIntelligenceService(FitnessCoachRepository repo){this.repo=repo;}
 public void refresh(LocalDate date){for(String metric:new String[]{"sleepMinutes","restingHeartRate","steps","distanceKm","exerciseMinutes"})for(int window:new int[]{7,28,90}){List<DailyHealthEntity>d=new ArrayList<>();for(int i=window-1;i>=0;i--){DailyHealthEntity x=repo.getDailyHealth(date.minusDays(i));if(x!=null)d.add(x);}repo.saveBaseline(baselines.calculate(metric,window,d));}Instant end=date.plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant(),start28=date.minusDays(27).atStartOfDay(ZoneId.systemDefault()).toInstant(),start7=date.minusDays(6).atStartOfDay(ZoneId.systemDefault()).toInstant();List<WorkoutEntity> all=repo.getWorkouts(),w7=new ArrayList<>(),w28=new ArrayList<>();for(WorkoutEntity w:all)if(w.startTime!=null&&w.startTime.compareTo(end)<0){if(w.startTime.compareTo(start28)>=0)w28.add(w);if(w.startTime.compareTo(start7)>=0)w7.add(w);}double ratio=load.acuteChronicRatio(load.total(w7),load.total(w28));RecoveryEntity r=recovery.calculate(date,repo.getDailyHealth(date),repo.getBaseline("sleepMinutes",28),repo.getBaseline("restingHeartRate",28),ratio,repo.getCheckIn(date));repo.saveRecovery(r);}
}
